    "description": "好耶，之前说的问题都解决了～ 然后我又发现有一个可以改进的地方：「正在加载预览」几个字现在每次换个文件的预览它总要闪一下下。可以改成比如说500ms内还没加载好才显示，这样加载得快的时候就不会闪了。",
