    "description": "新华社呼和浩特11月25日电（记者恩浩）内蒙古兴安盟阿尔山市常住人口3万多人，中心城区只有一条主街、六个红绿灯。小城横跨大兴安岭西南山麓，拥有百万亩原始森林、世界闻名的功能型矿泉群和亚洲最大的近期死火山玄武岩地貌。这里雪期长、雪质纯净，零下40摄氏度依然流淌的不冻河与百里雾凇相映，既是生态屏障，也是旅游秘境。 游客在内蒙古兴安盟阿尔山市哈拉哈河中体验不冻河漂流（无人机照片）。新华社记者 马金瑞 摄 “阿尔山，是一座山吗？”不少初来者这样…",
    "content": "新华社呼和浩特11月25日电（记者恩浩）内蒙古兴安盟阿尔山市常住人口3万多人，中心城区只有一条主街、六个红绿灯。小城横跨大兴安岭西南山麓，拥有百万亩原始森林、世界闻名的功能型矿泉群和亚洲最大的近期死火山玄武岩地貌。这里雪期长、雪质纯净，零下40摄氏度依然流淌的不冻河与百里雾凇相映，既是生态屏障，也是旅游秘境。 游客在内蒙古兴安盟阿尔山市哈拉哈河中体验不冻河漂流（无人机照片）。新华社记者 马金瑞 摄 “阿尔山，是一座山吗？”不少初来者这样问。 “阿尔山不是山。”这个问题，导游王海地每天要回答很多遍。“‘阿尔山’出自蒙…"
