    "content": "新华社新加坡11月25日电（记者舒畅 姬杨）以“为全球治理贡献亚洲智慧”为主题的2026“思想亚洲”论坛25日在新加坡举行。与会嘉宾围绕亚洲开放、创新与合作展开讨论，从媒体、智库、地方合作等方面探讨如何推动亚洲发展。 中国驻新加坡大使曹忠明在开幕致辞中说，亚洲的发展既要推动整体繁荣，也要关注不同国家、不同群体的发展需求，让共同发展的成果更好、更多地惠及地区国家和人民。 中国外文局副局长于运全在开幕致辞中说，“思想亚洲”论坛依托新加坡独特区位，秉持开放、合作、共赢理念，已迈入机制化建设阶段。他倡议各方持续以开放合作拓…"
