    "description": "新华社济南11月25日电 题：彼得·萨纳克：AI验证了黎曼猜想，而不是证明 新华社记者张力元、张昕怡 “我更愿意称之为验证，而不是证明。”对于日前AI辅助数学家证出黎曼猜想一事，首届潘承洞奖获得者、普林斯顿大学尤金·希金斯数学讲席教授彼得·萨纳克25日表示。 “数学的本质不仅是发现‘什么是真的’，更在于理解‘为什么它是真的’。”萨纳克说。在他看来，数学研究不仅是得到一个正确答案，更重要的是理解答案背后的逻辑，并将其转化为人类可以学习、交…",
    "content": "新华社济南11月25日电 题：彼得·萨纳克：AI验证了黎曼猜想，而不是证明 新华社记者张力元、张昕怡 “我更愿意称之为验证，而不是证明。”对于日前AI辅助数学家证出黎曼猜想一事，首届潘承洞奖获得者、普林斯顿大学尤金·希金斯数学讲席教授彼得·萨纳克25日表示。 “数学的本质不仅是发现‘什么是真的’，更在于理解‘为什么它是真的’。”萨纳克说。在他看来，数学研究不仅是得到一个正确答案，更重要的是理解答案背后的逻辑，并将其转化为人类可以学习、交流的知识。“一旦一个命题得到证明，它就成为一条定理，作为既定事实，再用来推导其他…"
