    "description": "新华社耶路撒冷11月25日电（记者王卓伦 黄耀漫）以色列议会25日初步通过一项法案，旨在限制总理任期、禁止受到特定刑事指控的议员组建政府，并建立在任总理面临相关刑事指控时解除其职务的机制。 据以色列媒体25日报道，当日的表决结果为65票赞成、48票反对。该法案由“以色列是我们的家园”党议员代表和正直党领导人加迪·艾森科特所在的政治阵营提出，拟对《基本法：政府》进行修订，将总理连续任职期限限制为8年，任期届满后8年内不得再担任政府职务；禁…",
    "content": "新华社耶路撒冷11月25日电（记者王卓伦 黄耀漫）以色列议会25日初步通过一项法案，旨在限制总理任期、禁止受到特定刑事指控的议员组建政府，并建立在任总理面临相关刑事指控时解除其职务的机制。 据以色列媒体25日报道，当日的表决结果为65票赞成、48票反对。该法案由“以色列是我们的家园”党议员代表和正直党领导人加迪·艾森科特所在的政治阵营提出，拟对《基本法：政府》进行修订，将总理连续任职期限限制为8年，任期届满后8年内不得再担任政府职务；禁止因涉及道德败坏的刑事罪名受到起诉的议员组建政府，并可经最高法院裁定解除面临此类…"
