    "content": "新华社香港11月25日电 亚洲数学联盟24日在香港成立，旨在促进亚洲各地数学界交流合作，推动数学研究、人才培育及跨学科创新发展。 成立典礼在香港中文大学（中大）举行，来自中国、印度、伊朗、日本、俄罗斯、韩国等国家及地区的数学家、学者及科研机构代表参加。 亚洲数学联盟主席、菲尔兹奖得主丘成桐表示，数学是推动科技创新的重要基础。亚洲数学联盟的成立，为区域内学者建立长远而开放的合作平台。他希望通过汇聚亚洲数学力量，促进科研创新与人才培育，并加强与世界各地数学界的联系。 中大常务副校长潘伟贤表示，中大一直致力推动基础研究及…"
