    "pub_date": "2026-11-25 22:45:33",
    "author": "",
    "description": "新华社喀布尔11月25日电（记者杜一方 张艺缤）阿富汗首都喀布尔警方发言人哈立德·扎德兰25日通报称，当日凌晨，警方在喀布尔击毙6名武装分子。 据阿富汗国家广播电视台报道，当地时间凌晨2时左右，警方与一伙武装分子在喀布尔第八警区爆发激烈交火，6名武装分子被击毙。警方从被击毙武装分子身上起获一些武器。 这是5天内喀布尔发生的第二起类似事件。21日夜间，喀布尔警方在交火中击毙3名武装分子，警方称其涉嫌参与针对银行运钞车的抢劫杀人案件。",
    "content": "新华社喀布尔11月25日电（记者杜一方 张艺缤）阿富汗首都喀布尔警方发言人哈立德·扎德兰25日通报称，当日凌晨，警方在喀布尔击毙6名武装分子。 据阿富汗国家广播电视台报道，当地时间凌晨2时左右，警方与一伙武装分子在喀布尔第八警区爆发激烈交火，6名武装分子被击毙。警方从被击毙武装分子身上起获一些武器。 这是5天内喀布尔发生的第二起类似事件。21日夜间，喀布尔警方在交火中击毙3名武装分子，警方称其涉嫌参与针对银行运钞车的抢劫杀人案件。"
