    "description": "新华社北京11月25日电（记者黄垚）记者从国家林草局25日召开的“三北”工程攻坚战工作推进会获悉，截至目前，今年“三北”工程建设任务已完成过九成，工程建设取得明显成效。 今年是“十五五”开局之年，也是“三北”工程攻坚战纵深推进的关键一年。国家林草局有关负责人在会上介绍，全年安排中央投资277亿元，实施重点项目328个，建设任务7448万亩。目前已完成各类建设任务6874万亩，进度为92.3%。 数据显示，自2023年“三北”工程攻坚战打…",
    "content": "新华社北京11月25日电（记者黄垚）记者从国家林草局25日召开的“三北”工程攻坚战工作推进会获悉，截至目前，今年“三北”工程建设任务已完成过九成，工程建设取得明显成效。 今年是“十五五”开局之年，也是“三北”工程攻坚战纵深推进的关键一年。国家林草局有关负责人在会上介绍，全年安排中央投资277亿元，实施重点项目328个，建设任务7448万亩。目前已完成各类建设任务6874万亩，进度为92.3%。 数据显示，自2023年“三北”工程攻坚战打响以来，“三北”工程建设推进力度加大。每年平均完成各类任务8000万亩以上，六期…"
