    "content": "老铺黄金中期股息预计合计派付约31.85亿元，董事长徐高明直接及间接对应股息近13亿元。 11月25日，古法手工金器第一品牌老铺黄金（06181.HK）在港交所公告，将派付截至2026年6月30日止六个月每股人民币18.02元（含税）的中期股息。该等中期股息将于2027年1月22日（星期五）分别以人民币（就未上市股份、港股通股份及H股“全流通”股份）及港元（就其他H股）派付予于2026年12月4日（星期五）名列于公司股东名册之股东。 公告称，根据2026年11月25日前五个营业日中国人民银行公布的港元对人民币的汇率…"
