    "content": "快科技11月25日消息， 米家便携电动剃须刀Pro直柄多效版今日开启众筹预约，众筹价329元，厂商建议零售价449元 ，将于12月2日10:00正式开启众筹。 新品采用修长的直筒手柄，机身由合金打造，经过15道工序处理，提供冰川银、暮岩灰2种配色。从外观来看，2个圆形刀网并排排列，手柄正面配有电源按键。 刀头采用双磁吸开合设计，保护盖、刀头与机身之间通过磁吸连接，拆下来清理胡茬、清洗刀头，再装回去都比较方便。 剃须部分采用环抱锁须切剃结构。简单说，就是通过波纹刀网上的弧形网槽引导胡须进入，再由内凹刀片配合完成切断。…"
