    "title": "朱光耀：AI时代关键在谁定规则 亚洲应有紧迫感无须走欧美路径",
    "link": "https://www.zaobao.com.sg/news/china/story20261125-10057844",
    "pub_date": "2026-11-25 22:11:10",
    "author": "",
    "description": "中国财政部原副部长朱光耀说，世界正处于以人工智能（AI）为代表的第四次产业革命的关键节点，分水岭不在于效率高低，而是谁来制定规则。他呼吁亚洲要有紧迫感，靠自己的数据和权益走入智能时代，不必重复欧美的路径。 朱光耀星期三（11月25日）在新加坡香格里拉酒店举行的“思想亚洲论坛”上发表上述观点。论坛由中国外文局、清华大学、厦门大学和新加坡南洋理工大学联办，探讨亚洲如何为全球治理贡献智慧。 朱光耀从2010年至2018年担任中国财政部副部长。…",
