    "content": "新华社北京11月25日电 英国能源监管机构天然气和电力市场办公室25日宣布，受中东冲突持续推高能源成本影响，2027年1月1日至3月31日期间，英国家庭能源价格上限将上调26%。 据路透社报道，英国能源价格上限是监管机构为供应商设定的最高收费标准，限定的是可向用户收取的最高单位价格和固定费用，适用于使用标准浮动费率的用户。 这是2022年2月3日在英国温切斯特一户人家拍摄的天然气灶。新华社发（蒂姆·爱尔兰摄） 根据该办公室发布的公告，届时英国家庭用电和用气年化费用上限将从此前的1723英镑升至2166英镑，上调44…"
