    "content": "新华社深圳11月25日电（记者王丰）记者从总部位于深圳的中国广核集团有限公司获悉，当日10时18分，中广核广东台山核电项目3号机组核岛第一罐混凝土开始浇筑，拉开台山核电二期工程建设序幕。 台山核电项目位于广东省江门市台山市赤溪镇。本次开工建设的3号机组属于台山核电项目二期工程，建成后年发电量超90亿千瓦时，可满足约100万人口的年生产生活用电需求。 台山核电项目规划6台百万千瓦级核电机组，分三期建设。其中，项目一期两台机组已于2019年9月7日全面建成投产；二期项目将采用高位收水自然通风冷却塔，依托大气热阱带出常规…"
