    "description": "开封市市政管网集中供热已全面运行。开封以电厂余热为核心热源，通过“热电联产”回收汽轮机做功后的蒸汽余热加热循环水，在城区范围内替代分散燃煤小锅炉，清洁热源已覆盖27万户家庭。 作者：杨静 王正一 邓亚彬 新华社音视频部制作",
    "content": "开封市市政管网集中供热已全面运行。开封以电厂余热为核心热源，通过“热电联产”回收汽轮机做功后的蒸汽余热加热循环水，在城区范围内替代分散燃煤小锅炉，清洁热源已覆盖27万户家庭。 作者：杨静 王正一 邓亚彬 新华社音视频部制作"
