    "description": "新华社北京11月25日电 英国廉价航空运营商易捷航空公司25日说，由于中东战事导致航空燃油价格飙升，该公司今年经营业绩不佳，去年10月至今年9月的上一财年净利润同比暴跌96%。 易捷航空在声明中说，尽管上一财年公司营收和乘客人次分别增加6%和3%，但受高油价拖累，公司净利润跌至2000万英镑（约合2600万美元）。 2020年10月31日，一架易捷航空公司航班降落在德国柏林-勃兰登堡机场。新华社发（阿妮卡·鲍尔摄） 易捷首席执行官肯顿·…",
    "content": "新华社北京11月25日电 英国廉价航空运营商易捷航空公司25日说，由于中东战事导致航空燃油价格飙升，该公司今年经营业绩不佳，去年10月至今年9月的上一财年净利润同比暴跌96%。 易捷航空在声明中说，尽管上一财年公司营收和乘客人次分别增加6%和3%，但受高油价拖累，公司净利润跌至2000万英镑（约合2600万美元）。 2020年10月31日，一架易捷航空公司航班降落在德国柏林-勃兰登堡机场。新华社发（阿妮卡·鲍尔摄） 易捷首席执行官肯顿·贾维斯说：“由于中东冲突及其对（航空运输）需求和燃油价格的影响，今年对航空公司来…"
