    "content": "新华社北京11月25日电 德国太阳能发电量今年创历史新高，首次突破100太瓦时、即1000亿千瓦时，成为该国第二大发电方式。 德新社25日援引德国弗劳恩霍夫太阳能系统研究所的数据报道，今年前9个月德国太阳能发电量就已经超过2025年全年的90太瓦时，创下新纪录。 报道说，100太瓦时相当于德国第二大城市汉堡去年用电量的9倍多，是20年前德国太阳能年发电量的大约45倍。 德国太阳能工业协会首席执行官卡斯滕·克尼希说，“光伏发电已经从一种小众技术发展为电力供应的主力”，不仅电价更便宜，而且帮助德国减少了能源进口，降低了…"
