    "content": "新华社乌兰巴托11月25日电（记者哈丽娜）在25日召开的蒙古国政府例行会议上，蒙古国自然环境与气候变化部通报东方省努姆鲁格自然保护区火灾损失评估进展，初步估计损失超9亿美元。此前报道显示火灾与日资企业人员活动有关。 蒙古国自然环境与气候变化部部长策·桑达格-奥其尔说，据卫星监测统计，本次火灾过火总面积达484383.7公顷，其中431592.8公顷位于努姆鲁格自然保护区范围内，占受灾总面积89.1%。环境部组建专业评估团队完成初步核查，火情波及森林、草原、河岸等多类生态系统。有8.1万公顷区域达到高和极高烧毁等级，…"
