    "content": "瓷面手绘卡通唐韵乐舞人物，仕女怀抱琵琶，童子击鼓，红绸飘逸，画风软萌生动。在位于河北唐山缸窑路的唐山凝境陶瓷科技有限公司展厅里，一套手绘国风骨质瓷餐具釉色莹润。 “这是为一家餐饮企业定制的。很多定制瓷只是在产品底部换个LOGO，但我们坚持专属设计，用器物叙事诠释企业的理念。”这家“燕赵老字号”企业，在第三代传承人李欣谌带领下，通过创新定制化模式把老手艺变成了新消费。 资深陶瓷设计师陈军正在绘制羊年葫芦如意瓶。（受访单位供图） 缸窑路是唐山陶瓷的起点，明代此地便设窑烧制陶瓷。六百年窑火，烧出了唐山这座城市的陶瓷产业根…"
