    "description": "我是 iCloud 重度用户，习惯随时访问自己的文档，但备忘录的编辑体验太糟糕了。 我想同时拥有飞书文档的编辑体验、iCloud 多端同步和多人实时协作，于是基于开源的 Quiet.md 做了飞记。 首发内测支持 Mac / iPhone / iPad，欢迎体验。 TestFlight 公开测试入口 如果你也经常在几台苹果设备之间切换着写，欢迎试试。同步或协作有哪里不顺手，可以直接回帖告诉我。",
